package com.daniil.wristlens.wear;
import android.app.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import com.daniil.wristlens.shared.*;import org.json.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="en-rUS-w240dp-h240dp-round-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class RecordingAudioUiTest {
 private void state(WatchActivity w,boolean rec,boolean paused,boolean audio,boolean capable){ReflectionHelpers.setField(w,"connected",true);ReflectionHelpers.setField(w,"node","phone");ReflectionHelpers.setField(w,"session","session");ReflectionHelpers.setField(w,"state",Wire.object("phase",rec?"recording":"ready","recording",rec,"paused",paused,"audio",audio,"microphoneSwitchable",capable,"elapsedMs",12000));ReflectionHelpers.setField(w,"lastFrame",SystemClock.elapsedRealtime());ReflectionHelpers.callInstanceMethod(w,"render");}
 @After public void after(){for(Dialog d:new ArrayList<>(ShadowDialog.getShownDialogs()))d.dismiss();}
 @Test public void micReplacesCameraAndSendsQuietToggleInSameRecording()throws Exception{try(var ctl=Robolectric.buildActivity(WatchActivity.class).create()){WatchActivity w=ctl.get();state(w,true,false,true,true);IconButton b=ReflectionHelpers.getField(w,"flipButton");assertEquals("Mute microphone",b.getContentDescription());b.performClick();Map<?,?> pending=ReflectionHelpers.getField(w,"pending");assertEquals(1,pending.size());Object p=pending.values().iterator().next();JSONObject command=ReflectionHelpers.getField(p,"command");assertEquals("audio",command.optString("op"));assertFalse(command.optBoolean("value"));assertFalse((Boolean)ReflectionHelpers.getField(p,"confirmSetting"));state(w,false,false,true,true);assertEquals(Strings.tr(com.daniil.wristlens.shared.R.string.wl_150),b.getContentDescription());}}
 @Test public void micWorksWhilePausedAndCannotInventMissingAudioTrack()throws Exception{try(var ctl=Robolectric.buildActivity(WatchActivity.class).create()){WatchActivity w=ctl.get();state(w,true,true,false,true);IconButton b=ReflectionHelpers.getField(w,"flipButton");assertTrue(b.isEnabled());assertEquals("Unmute microphone",b.getContentDescription());state(w,true,false,false,false);assertFalse(b.isEnabled());}}
 @Test public void separateSettingsStayOnSamePage()throws Exception{Activity a=Robolectric.buildActivity(Activity.class).setup().get();Strings.init(a);AtomicReference<JSONObject> sent=new AtomicReference<>();Controls.settings(a,Wire.object("audio",true,"previewAudio",false,"microphoneGranted",true),true,sent::set);Dialog d=ShadowDialog.getLatestDialog();assertTrue(((CheckBox)GallerySettingsTest.text(d,"Record microphone audio")).isChecked());assertFalse(((CheckBox)GallerySettingsTest.text(d,"Listen to phone microphone")).isChecked());GallerySettingsTest.text(d,"Listen to phone microphone").performClick();assertEquals("preview_audio",sent.get().optString("op"));assertTrue(d.isShowing());RoundMenuFrame root=RoundMenuTest.frame(d);RoundMenuTest.layout(root,480);RoundMenuTest.save(root,"audio-settings");a.finish();}
 @Test public void permissionRecoveryButtonAndMutedIconRender()throws Exception{try(var ctl=Robolectric.buildActivity(WatchActivity.class).create()){WatchActivity w=ctl.get();state(w,true,false,false,true);Bitmap bg=Bitmap.createBitmap(640,480,Bitmap.Config.ARGB_8888);new Canvas(bg).drawColor(0xff435764);((PreviewView)ReflectionHelpers.getField(w,"preview")).frame(bg,0,false);View root=((ViewGroup)w.findViewById(android.R.id.content)).getChildAt(0);RoundMenuTest.layout(root,480);RoundMenuTest.save(root,"recording-mic-muted");Controls.settings(w,Wire.object("microphoneGranted",false),true,c->{});assertTrue(GallerySettingsTest.has(ShadowDialog.getLatestDialog(),"Allow microphone on phone"));}}
 @Test public void phoneConfirmedAudioChangesRefreshWithoutClosingSettings(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();Strings.init(a);AtomicReference<JSONObject> state=new AtomicReference<>(Wire.object("audio",true,"previewAudio",false,"microphoneGranted",true));Controls.settings(a,state::get,true,c->{});Dialog d=ShadowDialog.getLatestDialog();state.set(Wire.object("audio",false,"previewAudio",true,"microphoneGranted",true));Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(450));assertTrue(d.isShowing());assertFalse(((CheckBox)GallerySettingsTest.text(d,"Record microphone audio")).isChecked());assertTrue(((CheckBox)GallerySettingsTest.text(d,"Listen to phone microphone")).isChecked());a.finish();}
}
